import { TimelineScrubber } from "@/components/application/timeline-scrubber/timeline-scrubber";
import { useLayoutEffect, useRef, useState } from "react";

const MOMENTS = [
  ["Morning swim", "Harbour baths"],
  ["Pottery class", "Clay studio"],
  ["Night market", "Old town"],
  ["Ferry ride", "North pier"],
  ["Book club", "Corner library"],
  ["Hill walk", "Ridge trail"],
  ["Coffee tasting", "Roastery"],
  ["Jazz night", "Basement bar"],
  ["Bike repair", "Workshop"],
  ["Garden shift", "Community plot"],
  ["Gallery opening", "East wing"],
  ["Picnic", "Riverside lawn"],
];

// A summer of entries, a day or a few apart, oldest first.
const ENTRIES = (() => {
  const out: { id: string; date: Date; label: string; place: string; hue: number }[] = [];
  const day = new Date(2026, 5, 2);
  const gaps = [1, 2, 3, 2, 1, 4, 2];
  for (let i = 0; day <= new Date(2026, 9, 18); i++) {
    const [label, place] = MOMENTS[(i * 5) % MOMENTS.length];
    out.push({ id: `entry-${i}`, date: new Date(day), label, place, hue: (i * 47) % 360 });
    day.setDate(day.getDate() + gaps[i % gaps.length]);
  }
  return out;
})();

const CARD = 144;
const GAP = 16;
const PITCH = CARD + GAP;
// A few entries back from the newest, so there are cards on both sides.
const START = ENTRIES.length - 3;
const short = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" });

export default function Demo() {
  const strip = useRef<HTMLDivElement>(null);
  const driving = useRef(0);
  const [index, setIndex] = useState(START);
  const [inView, setInView] = useState<[number, number]>([START, START]);

  const measure = () => {
    const el = strip.current;
    if (!el) return;
    const centre = el.scrollLeft / PITCH;
    const half = Math.max(0, (el.clientWidth / PITCH - 1) / 2);
    setInView([centre - half, centre + half]);
    // Scrolled by hand: the scrubber follows. Scrolled by the scrubber: it already knows.
    if (performance.now() - driving.current > 120) setIndex(Math.round(centre));
  };

  // The scroll to the first entry also measures the view.
  useLayoutEffect(() => {
    if (strip.current) strip.current.scrollLeft = START * PITCH;
  }, []);

  // The strip glides with the marker; snapping waits until it stops.
  const follow = (position: number) => {
    const el = strip.current;
    if (!el) return;
    driving.current = performance.now();
    el.style.scrollSnapType = "none";
    el.scrollLeft = position * PITCH;
    window.clearTimeout(Number(el.dataset.snap));
    el.dataset.snap = String(window.setTimeout(() => (el.style.scrollSnapType = ""), 160));
  };

  return (
    <div className="mx-auto flex w-full max-w-[34rem] flex-col gap-1 text-text-primary">
      <div
        ref={strip}
        onScroll={measure}
        className="flex snap-x snap-mandatory overflow-x-auto py-2 [mask-image:linear-gradient(90deg,transparent,#000_14%,#000_86%,transparent)] [scrollbar-width:none]"
        style={{ gap: GAP, paddingInline: `calc(50% - ${CARD / 2}px)` }}
      >
        {ENTRIES.map((entry) => (
          <article
            key={entry.id}
            className="shrink-0 snap-center text-center"
            style={{ width: CARD }}
          >
            <p className="text-sm text-text-secondary">{short.format(entry.date)}</p>
            <div
              className="mx-auto mt-3 h-24 w-28 rounded-2xl"
              style={{
                background: `linear-gradient(140deg, oklch(0.86 0.09 ${entry.hue}), oklch(0.7 0.13 ${entry.hue + 40}))`,
              }}
            />
            <p className="mt-3 truncate text-sm font-medium">{entry.label}</p>
            <p className="truncate text-sm text-text-secondary">{entry.place}</p>
          </article>
        ))}
      </div>
      <TimelineScrubber
        items={ENTRIES}
        value={index}
        onChange={setIndex}
        onPositionChange={follow}
        inView={inView}
        aria-label="Summer timeline"
      />
    </div>
  );
}

