"use client";

import { LogRow, useLogMotion, useRevealTicker, WorkingRow } from "@/components/application/agent-log/agent-log";
import { Button } from "@/components/base/buttons/button";
import { RiCheckLine, RiFileSearchLine } from "@remixicon/react";
import { useState } from "react";

const FINDINGS = [
  "Read the component specification",
  "Reviewed the existing interaction patterns",
  "Verified semantic colors and typography",
  "Prepared the implementation notes",
];

function LogSequence({ run, onComplete }: { run: boolean; onComplete: () => void }) {
  const reduce = useLogMotion();
  const revealed = useRevealTicker({
    total: FINDINGS.length,
    run,
    stepInterval: 850,
    startDelay: 250,
    onComplete,
  });
  return (
    <div className="flex min-h-44 flex-col gap-2">
      <div className="flex items-center gap-2 text-body-medium text-text-primary">
        <RiFileSearchLine className="size-4 text-foreground-icon-secondary" />
        Reviewing the component
      </div>
      <ol aria-label="Agent work log" className="ml-2" aria-live="polite">
        {FINDINGS.slice(0, revealed).map((finding, index) => (
          <LogRow key={finding} first={index === 0} last={index === revealed - 1} reduce={reduce}>
            <div className="flex items-center gap-2 py-1 text-body-regular text-text-secondary">
              <RiCheckLine className="size-4 shrink-0 text-foreground-icon-secondary" />
              {finding}
            </div>
          </LogRow>
        ))}
      </ol>
      {revealed < FINDINGS.length ? (
        <WorkingRow
          label={run ? "Checking the next step" : "Paused"}
          reduce={reduce}
          className="ml-6"
        />
      ) : (
        <p className="ml-6 text-body-2-medium text-text-secondary">Review complete.</p>
      )}
    </div>
  );
}

export default function AgentLogDemo() {
  const [run, setRun] = useState(true);
  const [finished, setFinished] = useState(false);
  const [replay, setReplay] = useState(0);
  return (
    <div className="flex w-full max-w-lg flex-col gap-4 rounded-3xl border border-border-button-default bg-background-primary-default p-5">
      <LogSequence key={replay} run={run} onComplete={() => setFinished(true)} />
      <div className="flex gap-2 border-t border-separator-border pt-4">
        <Button
          variant="secondary"
          size="small"
          disabled={finished}
          onClick={() => setRun((value) => !value)}
        >
          {run ? "Pause" : "Resume"}
        </Button>
        <Button
          variant="secondary"
          size="small"
          onClick={() => {
            setReplay((value) => value + 1);
            setFinished(false);
            setRun(true);
          }}
        >
          Replay
        </Button>
      </div>
    </div>
  );
}

