"use client";

import { ChartCard } from "@/components/application/charts/chart-card";
import { Button } from "@/components/base/buttons/button";
import { useState } from "react";

const PERIODS = [
  [
    { label: "Mon", value: 28 },
    { label: "Tue", value: 42 },
    { label: "Wed", value: 35 },
    { label: "Thu", value: 56 },
    { label: "Fri", value: 49 },
  ],
  [
    { label: "Mon", value: 36 },
    { label: "Tue", value: 31 },
    { label: "Wed", value: 52 },
    { label: "Thu", value: 44 },
    { label: "Fri", value: 61 },
  ],
];

export default function ChartCardDemo() {
  const [period, setPeriod] = useState(0);
  const [active, setActive] = useState<number | null>(null);
  const data = PERIODS[period]!;
  const total = data.reduce((value, point) => value + point.value, 0);
  return (
    <div className="w-full max-w-lg">
      <ChartCard
        label={active === null ? "Completed tasks" : data[active]!.label}
        value={active === null ? total : data[active]!.value}
        caption={active === null ? "Hover a bar to inspect a day" : "Tasks completed on this day"}
        pulseKey={active}
        height={300}
        action={
          <Button
            variant="secondary"
            size="small"
            onClick={() => {
              setPeriod((value) => (value + 1) % PERIODS.length);
              setActive(null);
            }}
          >
            {period === 0 ? "This week" : "Last week"}
          </Button>
        }
      >
        <div className="flex h-full items-stretch gap-5 pt-3">
          {data.map((point, index) => (
            <div key={point.label} className="flex min-w-0 flex-1 flex-col items-center gap-2">
              <button
                type="button"
                aria-label={`${point.label}: ${point.value} completed tasks`}
                onMouseEnter={() => setActive(index)}
                onMouseLeave={() => setActive(null)}
                onFocus={() => setActive(index)}
                onBlur={() => setActive(null)}
                className="relative w-full flex-1 rounded-lg bg-chart-track outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring"
              >
                <span
                  className="absolute inset-x-0 bottom-0 rounded-lg bg-chart-2 transition-[height,opacity] duration-300 motion-reduce:transition-none"
                  style={{
                    height: `${(point.value / 70) * 100}%`,
                    opacity: active !== null && active !== index ? 0.4 : 1,
                  }}
                />
              </button>
              <span className="text-caption-1-medium text-text-secondary">{point.label}</span>
            </div>
          ))}
        </div>
      </ChartCard>
    </div>
  );
}

